def bplan(n, p, cur=False, hot=False):
    return card(row(h3(n,20), grow(), chip('current','lime') if cur else '', gap=8), f'<div style="font-family: {HF}; font-weight: 800; font-size: 36px">{p}<span style="font-size: 14px; color: {T["mu"]}; font-family: {BF}; font-weight: 500"> / mo</span></div>', btn('Current plan' if cur else 'Choose','secondary' if cur else 'primary', full=True), pad=20, style=f'border: 2px solid {T["lime"] if hot else T["bd"]}')
modal = overlay(row(bubble('card','lime',52), col(H('Upgrade to Business',26), small('Billed monthly · cancel any time'), gap=2), gap=12) +
    kv([('Price','$99.00 / month'),('Today, prorated','$50.00'),('You’ll pay in naira','≈ ₦[AMOUNT]: exact amount shown by Paystack before you confirm'),('Payment provider','Paystack')]) +
    check('I authorize Nelio to charge me $99 every month until I cancel.', True) + btn('Continue to Paystack','primary','arrowr',full=True,size='lg') + small('No charge happens until you confirm on the next screen.'), maxw=560)
